-- ============================================================
-- Pravarthana Margarekha 2026-27 — annual plan content (key-value JSONB)
-- Run in the Supabase SQL editor. Idempotent (safe to re-run).
-- ============================================================

CREATE TABLE IF NOT EXISTS plan_content (
  key         text PRIMARY KEY,
  value       jsonb NOT NULL,
  sort_order  int   NOT NULL DEFAULT 0,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE plan_content ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='plan_content' AND policyname='plan_content_public_read') THEN
    CREATE POLICY "plan_content_public_read" ON plan_content FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='plan_content' AND policyname='plan_content_auth_all') THEN
    CREATE POLICY "plan_content_auth_all" ON plan_content FOR ALL USING (auth.role() = 'authenticated');
  END IF;
END $$;

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:meta', '{"org":"ചെറുപുഷ്പ മിഷൻ ലീഗ് · കൽപ്പറ്റ മേഖല","title":"പ്രവർത്തന മാർഗ്ഗരേഖ","yearLabel":"2026 – 27","yearTheme":"വേരുകളറിയാം · വിശ്വാസം ജീവിക്കാം · സമൂഹം പണിയാം","subTheme":"മാർത്തോമായുടെ വിശ്വാസം, ഫ്രാൻസിസിന്റെ സ്നേഹം, നാളെയുടെ സമൂഹം","subThemeLine":"കൊച്ചുത്രേസ്യയോടൊപ്പം സഭ പണിയാം — ചെറിയ നല്ല പ്രവൃത്തികളിലൂടെ ജീവനുള്ള കല്ലുകളായി","objectives":["നസ്രാണി സ്വത്വബോധം ശക്തിപ്പെടുത്തുക","സീറോ മലബാർ സഭയുടെ ചരിത്രവും പൈതൃകവും പരിചയപ്പെടുത്തുക","വിശ്വാസ ജീവിതത്തിൽ ആഴം വളർത്തുക","ചെറുപുഷ്പ മിഷൻ ലീഗ് അംഗങ്ങളെ നേതൃത്വത്തിലേക്ക് വളർത്തുക","കുടുംബം, ഇടവക, സമൂഹം എന്നിവയെ ബന്ധിപ്പിക്കുക","വിശുദ്ധ ഫ്രാൻസിസിന്റെ സ്നേഹവും സേവനവും ജീവിതമൂല്യമാക്കുക"],"projects":[{"title":"നസ്രാണി എക്സ്പ്ലോറർ പാസ്പോർട്ട്","desc":"കളികളിലൂടെയും ദൗത്യങ്ങളിലൂടെയും നസ്രാണി വിശ്വാസവും പൈതൃകവും കണ്ടെത്തുന്ന വർഷം നീളുന്ന സാഹസിക യാത്ര."},{"title":"ഫ്രാൻസിസ് 100","desc":"വിശുദ്ധ ഫ്രാൻസിസിന്റെ മാതൃകയിൽ 100 സ്നേഹ-സേവന പ്രവർത്തനങ്ങൾ പൂർത്തിയാക്കുന്ന കാരുണ്യയാത്ര."},{"title":"ഒരു അംഗം – ഒരു സേവനം","desc":"ഓരോ CML അംഗവും സമൂഹത്തിനായി ഒരു വ്യക്തിഗത സേവന ദൗത്യം ഏറ്റെടുക്കുന്ന പദ്ധതി."},{"title":"കുടുംബ വിശ്വാസ വൃക്ഷം","desc":"തലമുറകളിലൂടെ കൈമാറപ്പെട്ട വിശ്വാസ പാരമ്പര്യം കുടുംബവൃക്ഷമായി രേഖപ്പെടുത്തുന്ന പ്രവർത്തനം."}],"buildChurch":{"intro":"വിശുദ്ധ കൊച്ചുത്രേസ്യയോടൊപ്പം — ജീവനുള്ള കല്ലുകളായി സഭ പണിയുന്ന വർഷം","quote":"“നിങ്ങളും ജീവനുള്ള കല്ലുകളെപ്പോലെ ആത്മീയ ഭവനമായി പണിയപ്പെടുന്നു.”","quoteRef":"— 1 പത്രോസ് 2:5","littleWay":"കൊച്ചുത്രേസ്യയുടെ ‘ചെറിയ വഴി’ — ഓരോ ചെറിയ നല്ല പ്രവൃത്തിയും ഒരു കല്ലാണ്. വർഷം മുഴുവൻ ശേഖരിക്കുന്ന കല്ലുകൾ ചേർന്ന് വർഷാന്ത്യം ഒരു ദേവാലയമായി മാറുന്നു.","pillars":[{"label":"അംഗം","title":"ഒരു കുട്ടി – ഒരു കല്ല്","desc":"ഓരോ അംഗവും ജീവനുള്ള കല്ലായി മാറി സഭയുടെ ആത്മീയ ഭവനം നിർമ്മിക്കുന്ന പദ്ധതി."},{"label":"ശാഖ","title":"ശാഖ പണിയാം","desc":"പ്രാർത്ഥനയിലും സേവനത്തിലും അംഗത്വത്തിലും വളരുന്ന ശക്തമായ CML ശാഖകളെ രൂപപ്പെടുത്തുന്ന പദ്ധതി."},{"label":"വിശുദ്ധി","title":"നാളെയുടെ വിശുദ്ധർ","desc":"കൊച്ചുത്രേസ്യയുടെ ചെറിയ വഴിയിലൂടെ ഓരോ കുട്ടിയും ഒരു സദ്ഗുണം തിരഞ്ഞെടുത്ത് വളർത്തുന്നു."},{"label":"മിഷൻ","title":"മിഷൻ ദേവാലയം പണിയാം","desc":"ഓരോ ശാഖയും ഒരു മിഷൻ പ്രദേശം ഏറ്റെടുത്ത് അവിടത്തെ സഭാവളർച്ചയിൽ പങ്കാളിയാകുന്നു."}],"parts":[{"monthKey":"2026-07","ml":"അടിത്തറ","en":"St Thomas Foundation","index":1},{"monthKey":"2026-08","ml":"ചരിത്ര തൂണുകൾ","en":"Nazrani History Pillars","index":2},{"monthKey":"2026-09","ml":"സംസ്കാര ജാലകങ്ങൾ","en":"Culture Windows","index":3},{"monthKey":"2026-10","ml":"മിഷൻ ഗോപുരം","en":"Mission Tower","index":4},{"monthKey":"2026-11","ml":"സേവന വാതിൽ","en":"Service Door","index":5},{"monthKey":"2026-12","ml":"കുടുംബ അൾത്താര","en":"Family Altar","index":6},{"monthKey":"2027-01","ml":"കേരള സംഭാവന ഗാലറി","en":"Kerala Contribution Gallery","index":7},{"monthKey":"2027-02","ml":"കാരുണ്യ കവാടം","en":"Mercy Gate","index":8},{"monthKey":"2027-03","ml":"വിശുദ്ധ കുർബാന മണ്ഡപം","en":"Eucharistic Sanctuary","index":9},{"monthKey":"2027-04","ml":"നേതൃത്വ മണിഗോപുരം","en":"Leadership Bell Tower","index":10},{"monthKey":"2027-05","ml":"പൂർത്തിയായ ദേവാലയം","en":"Completed Church","index":11}]},"virtues":["വിനയം","കാരുണ്യം","അനുസരണം","വിശുദ്ധി","സന്തോഷം"],"awards":["മാർത്തോമാ ഹെറിറ്റേജ് ട്രോഫി","മികച്ച ഷാഖ","മികച്ച നസ്രാണി എക്സ്പ്ലോറർ","മികച്ച കുടുംബ വിശ്വാസ പുരസ്കാരം","ഫ്രാൻസിസ് സേവന പുരസ്കാരം","മികച്ച സമൂഹ നിർമ്മാണ പദ്ധതി"]}'::jsonb, 0)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-07', '{"index":1,"monthKey":"2026-07","monthEn":"JULY 2026","monthMl":"ജൂലൈ","accent":"#DE8C6F","actionTheme":"മാർത്തോമാ നസ്രാണി മാസം","churchLine":"ദേവാലയം പണിയുന്നു · അടിത്തറ","churchPart":{"ml":"അടിത്തറ","en":"St Thomas Foundation","index":1,"total":11},"tagline":"ഞങ്ങൾ മാർത്തോമാ നസ്രാണികൾ","description":"വിശുദ്ധ തോമാശ്ലീഹയിൽ നിന്ന് ഇന്നത്തെ നസ്രാണി സമൂഹത്തിലേക്കുള്ള ചരിത്രാന്വേഷണ യാത്ര.","virtue":"വിശ്വാസം","stones":["ഒരു പുതിയ പ്രാർത്ഥന പഠിക്കുക","വി. കുർബാനയിൽ പങ്കെടുക്കുക","ഒരു പുരാതന കുരിശ് രേഖപ്പെടുത്തുക","കുടുംബ വേരുകൾ അന്വേഷിക്കുക"],"feastDays":[{"date":"3 ജൂലൈ","day":"വെള്ളി","name":"വി. തോമാശ്ലീഹായുടെ തിരുനാൾ","type":"തിരുനാൾ"}],"programs":[{"title":"നസ്രാണി എക്സ്പ്ലോറർ പാസ്പോർട്ട് ഉദ്ഘാടനം","desc":"വർഷം മുഴുവൻ പ്രവർത്തനങ്ങൾ രേഖപ്പെടുത്തുന്ന പാസ്പോർട്ട് വിതരണം."},{"title":"മാർത്തോമാ ചരിത്ര ടൈംലൈൻ","desc":"AD 52 മുതലുള്ള നസ്രാണി ചരിത്രം ചിത്രരൂപത്തിൽ."},{"title":"നസ്രാണി ക്വിസ്","desc":"നസ്രാണി പൈതൃകത്തെക്കുറിച്ചുള്ള മത്സരം."},{"title":"പുരാതന കുരിശുകൾ കണ്ടെത്തൽ","desc":"നാട്ടിലെ പുരാതന കുരിശുകളും ദേവാലയങ്ങളും സന്ദർശനം."},{"title":"കുടുംബ വംശവൃക്ഷ നിർമ്മാണം","desc":"ഓരോ കുടുംബവും വിശ്വാസ വേരുകൾ വരയ്ക്കുന്നു."},{"title":"വിശുദ്ധ തോമാശ്ലീഹ ദിനാഘോഷം","desc":"ജൂലൈ 3-ന് സമൂഹതലത്തിൽ തിരുനാൾ ആഘോഷം."}]}'::jsonb, 1)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-08', '{"index":2,"monthKey":"2026-08","monthEn":"AUGUST 2026","monthMl":"ആഗസ്റ്റ്","accent":"#E3B85C","actionTheme":"കേരളം പണിത നസ്രാണികൾ","churchLine":"ദേവാലയം പണിയുന്നു · ചരിത്ര തൂണുകൾ","churchPart":{"ml":"ചരിത്ര തൂണുകൾ","en":"Nazrani History Pillars","index":2,"total":11},"tagline":"കേരളത്തിന് നസ്രാണികളുടെ സംഭാവന","description":"കേരളത്തിന്റെ വിദ്യാഭ്യാസ, ആരോഗ്യ, സാമൂഹിക മേഖലകളിൽ നസ്രാണികളുടെ സംഭാവനകൾ കണ്ടെത്തുകയും അവതരിപ്പിക്കുകയും ചെയ്യുന്ന പദ്ധതി.","virtue":"കൃതജ്ഞത","stones":["ഒരു മുതിർന്നയാളെ അഭിമുഖം ചെയ്യുക","ഒരു പഴയ കുടുംബ രേഖ ശേഖരിക്കുക","നാടിനായി ഒരു നന്മ ചെയ്യുക"],"feastDays":[{"date":"15 ആഗസ്റ്റ്","day":"ശനി","name":"പരിശുദ്ധ കന്യകാമറിയത്തിന്റെ സ്വർഗ്ഗാരോപണം","type":"തിരുനാൾ"},{"date":"15 ആഗസ്റ്റ്","day":"ശനി","name":"സ്വാതന്ത്ര്യദിനം","type":"ദേശീയം"}],"programs":[{"title":"കേരള ചരിത്ര പഠന പദ്ധതി","desc":"നസ്രാണികളുടെ സാമൂഹിക സംഭാവനകൾ പഠിക്കുന്നു."},{"title":"മുത്തശ്ശൻ-മുത്തശ്ശി അഭിമുഖം","desc":"മുതിർന്നവരിൽ നിന്ന് കുടുംബ കഥകൾ ശേഖരിക്കുന്നു."},{"title":"പഴയ കുടുംബ രേഖകൾ ശേഖരണം","desc":"പഴയ ഫോട്ടോകളും രേഖകളും സംരക്ഷിക്കുന്നു."},{"title":"ഹെറിറ്റേജ് പ്രദർശനം","desc":"ശേഖരിച്ച വസ്തുക്കളുടെ പൊതു പ്രദർശനം."},{"title":"സ്വാതന്ത്ര്യദിന ദേശഭക്തി പരിപാടി","desc":"ആഗസ്റ്റ് 15-ന് ദേശസ്നേഹ പരിപാടി."}]}'::jsonb, 2)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-09', '{"index":3,"monthKey":"2026-09","monthEn":"SEPTEMBER 2026","monthMl":"സെപ്റ്റംബർ","accent":"#DF94A7","actionTheme":"നസ്രാണി സംസ്കാര മാസം","churchLine":"ദേവാലയം പണിയുന്നു · സംസ്കാര ജാലകങ്ങൾ","churchPart":{"ml":"സംസ്കാര ജാലകങ്ങൾ","en":"Culture Windows","index":3,"total":11},"tagline":"നസ്രാണി ജീവിതരീതി","description":"നസ്രാണി ഭക്ഷണവും കലയും ആചാരങ്ങളും പാരമ്പര്യങ്ങളും പരിചയപ്പെടുത്തുന്ന സാംസ്കാരിക ആഘോഷം.","virtue":"വിനയം","stones":["ഒരു നസ്രാണി ആചാരം പഠിക്കുക","പേശഹ അപ്പം ഉണ്ടാക്കാൻ സഹായിക്കുക","മാർത്തോമാ കുരിശ് വരയ്ക്കുക"],"feastDays":[{"date":"5 സെപ്റ്റം","day":"ശനി","name":"വി. മദർ തെരേസ","type":"തിരുനാൾ"},{"date":"8 സെപ്റ്റം","day":"ചൊവ്വ","name":"മാതാവിന്റെ ജനന തിരുനാൾ","type":"തിരുനാൾ"}],"programs":[{"title":"പേശഹ അപ്പം ശില്പശാല","desc":"പരമ്പരാഗത പേശഹ അപ്പം ഉണ്ടാക്കാൻ പഠിക്കുന്നു."},{"title":"നസ്രാണി ഭക്ഷ്യമേള","desc":"നസ്രാണി പരമ്പരാഗത വിഭവങ്ങളുടെ മേള."},{"title":"നസ്രാണി വേഷദിനം","desc":"പരമ്പരാഗത വേഷം അണിയുന്ന ദിനം."},{"title":"മാർത്തോമാ കുരിശ് പഠനം","desc":"മാർത്തോമാ കുരിശിന്റെ അർത്ഥവും ചരിത്രവും."},{"title":"കുടുംബ സംസ്കാര രാത്രി","desc":"കല, പാട്ട്, കഥ ചേർന്ന കുടുംബ സന്ധ്യ."}]}'::jsonb, 3)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-10', '{"index":4,"monthKey":"2026-10","monthEn":"OCTOBER 2026","monthMl":"ഒക്ടോബർ","accent":"#93BE7E","actionTheme":"മിഷൻ മാസം","churchLine":"ദേവാലയം പണിയുന്നു · മിഷൻ ഗോപുരം","churchPart":{"ml":"മിഷൻ ഗോപുരം","en":"Mission Tower","index":4,"total":11},"tagline":"ഓരോ നസ്രാണിയും ഒരു മിഷണറി","description":"പ്രാർത്ഥനയിൽ നിന്ന് സേവനത്തിലേക്കും സേവനത്തിൽ നിന്ന് സമൂഹനിർമ്മാണത്തിലേക്കും.","virtue":"മിഷൻ തീക്ഷ്ണത","stones":["മിഷനായി പ്രാർത്ഥിക്കുക","ഒരു മിഷൻ സംഭാവന നൽകുക","ഒരു സുഹൃത്തിനെ CML-ലേക്ക് ക്ഷണിക്കുക"],"feastDays":[{"date":"1 ഒക്ടോബർ","day":"വ്യാഴം","name":"വി. കൊച്ചുത്രേസ്യ","type":"തിരുനാൾ"},{"date":"4 ഒക്ടോബർ","day":"ഞായർ","name":"വി. ഫ്രാൻസിസ് അസീസി","type":"തിരുനാൾ"},{"date":"18 ഒക്ടോബർ","day":"ഞായർ","name":"ലോക മിഷൻ ഞായർ","type":"ദിനം"}],"programs":[{"title":"ഫ്രാൻസിസ് ജൂബിലി അനുസ്മരണം","desc":"800-ാം ജൂബിലിയോടനുബന്ധിച്ച പ്രാർത്ഥനയും സേവനവും."},{"title":"മിഷൻ ഗ്രാമ സഹായം","desc":"ഒരു മിഷൻ ഗ്രാമത്തിന് സഹായം എത്തിക്കുന്നു."},{"title":"സേവന ദിനം","desc":"സമൂഹത്തിനായി ഒരു ദിവസത്തെ കൂട്ടായ സേവനം."},{"title":"മിഷനറിമാരുമായി സംവാദം","desc":"മിഷൻ പ്രവർത്തകരുമായി നേരിട്ടുള്ള സംവാദം."},{"title":"മിഷൻ വീഡിയോ മത്സരം","desc":"മിഷൻ സന്ദേശം നൽകുന്ന ഹ്രസ്വ വീഡിയോ മത്സരം."}]}'::jsonb, 4)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-11', '{"index":5,"monthKey":"2026-11","monthEn":"NOVEMBER 2026","monthMl":"നവംബർ","accent":"#8DB6D6","actionTheme":"സമൂഹ നിർമ്മാണ മാസം","churchLine":"ദേവാലയം പണിയുന്നു · സേവന വാതിൽ","churchPart":{"ml":"സേവന വാതിൽ","en":"Service Door","index":5,"total":11},"tagline":"സമൂഹത്തിനായി ജീവിക്കാം","description":"വിശ്വാസത്തെ പ്രവർത്തിയാക്കി സ്വന്തം നാടിനും സമൂഹത്തിനും മാറ്റം സൃഷ്ടിക്കുന്ന യുവജന പ്രസ്ഥാനം.","virtue":"സേവനം","stones":["ഒരു രോഗിയെ സന്ദർശിക്കുക","ഒരു വൃക്ഷത്തൈ നടുക","ഗ്രാമ ശുചീകരണത്തിൽ പങ്കെടുക്കുക"],"feastDays":[{"date":"1 നവംബർ","day":"ഞായർ","name":"സകല വിശുദ്ധരുടെയും തിരുനാൾ","type":"തിരുനാൾ"},{"date":"2 നവംബർ","day":"തിങ്കൾ","name":"മരിച്ച വിശ്വാസികളുടെ ദിനം","type":"ദിനം"}],"programs":[{"title":"ഗ്രാമ ശുചീകരണം","desc":"സ്വന്തം നാട് വൃത്തിയാക്കുന്ന കൂട്ടായ്മ."},{"title":"വയോജന സന്ദർശനം","desc":"വൃദ്ധസദനങ്ങളും ഏകാകികളും സന്ദർശിക്കുന്നു."},{"title":"ആശുപത്രി സേവനം","desc":"രോഗികൾക്ക് സാന്ത്വനവും സഹായവും."},{"title":"വൃക്ഷതൈ നട്ട് സംരക്ഷിക്കൽ","desc":"പ്രകൃതി സംരക്ഷണത്തിനായി മരം നടൽ."},{"title":"ഒരു അംഗം ഒരു സേവനം റിപ്പോർട്ട്","desc":"ഓരോ അംഗവും ഏറ്റെടുത്ത സേവനത്തിന്റെ റിപ്പോർട്ട്."}]}'::jsonb, 5)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2026-12', '{"index":6,"monthKey":"2026-12","monthEn":"DECEMBER 2026","monthMl":"ഡിസംബർ","accent":"#6FB39E","actionTheme":"കുടുംബ മാസം","churchLine":"ദേവാലയം പണിയുന്നു · കുടുംബ അൾത്താര","churchPart":{"ml":"കുടുംബ അൾത്താര","en":"Family Altar","index":6,"total":11},"tagline":"നസ്രാണി കുടുംബം","description":"കുടുംബത്തെ വിശ്വാസത്തിന്റെ ആദ്യ വിദ്യാലയമാക്കുക. ആദ്യ പുൽക്കൂട് ഒരുക്കിയ വി. ഫ്രാൻസിസ് അസീസിയോടൊപ്പം ശതാബ്ദി ജൂബിലിയുടെ സമാപനം.","virtue":"സ്നേഹം","stones":["കുടുംബ പ്രാർത്ഥനയിൽ പങ്കെടുക്കുക","ക്രിസ്മസ് കാരുണ്യം പങ്കിടുക","കുടുംബ അൾത്താര ഒരുക്കുക"],"feastDays":[{"date":"3 ഡിസംബർ","day":"വ്യാഴം","name":"വി. ഫ്രാൻസിസ് സേവ്യർ തിരുനാൾ","type":"തിരുനാൾ"},{"date":"8 ഡിസംബർ","day":"ചൊവ്വ","name":"അമലോത്ഭവ മാതാവ്","type":"തിരുനാൾ"},{"date":"25 ഡിസംബർ","day":"വെള്ളി","name":"ക്രിസ്മസ്","type":"തിരുനാൾ"},{"date":"28 ഡിസംബർ","day":"തിങ്കൾ","name":"ഫ്രാൻസിസ് ശതാബ്ദി ജൂബിലി സമാപനം","type":"ജൂബിലി"}],"programs":[{"title":"കുടുംബ പ്രാർത്ഥന വാരം","desc":"ഓരോ കുടുംബവും ഒരാഴ്ച ഒരുമിച്ച് ജപമാല ചൊല്ലുന്നു."},{"title":"കുടുംബ വിശ്വാസ വൃക്ഷം","desc":"കുടുംബത്തിന്റെ വിശ്വാസ പാരമ്പര്യം രേഖപ്പെടുത്തുന്നു."},{"title":"ക്രിസ്മസ് കാരുണ്യ പ്രവർത്തനം","desc":"ദരിദ്ര കുടുംബങ്ങൾക്ക് ക്രിസ്മസ് സഹായം."},{"title":"കുടുംബ കലോത്സവം","desc":"കുടുംബങ്ങൾ ഒത്തുചേരുന്ന കലാ സന്ധ്യ."},{"title":"ഫ്രാൻസിസ് പുൽക്കൂട് ഒരുക്കൽ","desc":"വി. ഫ്രാൻസിസ് അസീസിയുടെ ആദ്യ പുൽക്കൂട് മാതൃകയിൽ ഭവന പുൽക്കൂട്."}]}'::jsonb, 6)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2027-01', '{"index":7,"monthKey":"2027-01","monthEn":"JANUARY 2027","monthMl":"ജനുവരി","accent":"#A99AD3","actionTheme":"കേരളത്തിനായുള്ള നസ്രാണികൾ","churchLine":"ദേവാലയം പണിയുന്നു · കേരള സംഭാവന ഗാലറി","churchPart":{"ml":"കേരള സംഭാവന ഗാലറി","en":"Kerala Contribution Gallery","index":7,"total":11},"tagline":"നാടിനായി വിശ്വാസം","description":"കേരള നവോത്ഥാനത്തിൽ നസ്രാണികളുടെ പങ്ക് തിരിച്ചറിയുകയും പ്രചരിപ്പിക്കുകയും ചെയ്യുക.","virtue":"ധൈര്യം","stones":["ഒരു നവോത്ഥാന നായകനെക്കുറിച്ച് പഠിക്കുക","നാടിനായി ഒരു സേവനം ചെയ്യുക","ഹെറിറ്റേജ് ക്വിസിൽ പങ്കെടുക്കുക"],"feastDays":[{"date":"3 ജനുവരി","day":"ഞായർ","name":"വി. ചാവറ കുര്യാക്കോസ് അച്ചൻ","type":"തിരുനാൾ"},{"date":"14 ജനുവരി","day":"വ്യാഴം","name":"വി. ദേവസഹായം പിള്ള","type":"തിരുനാൾ"}],"programs":[{"title":"ചരിത്ര പ്രഭാഷണം","desc":"കേരള നവോത്ഥാനത്തിലെ നസ്രാണി പങ്ക്."},{"title":"വിദ്യാഭ്യാസ രംഗത്തെ സംഭാവനകൾ","desc":"സ്കൂളുകളും കോളേജുകളും സ്ഥാപിച്ച ചരിത്രം."},{"title":"സാമൂഹിക പരിഷ്കരണ പഠനം","desc":"സാമൂഹിക മാറ്റത്തിന് നൽകിയ സംഭാവനകൾ."},{"title":"ഹെറിറ്റേജ് ക്വിസ് ലീഗ്","desc":"മേഖലാതല പൈതൃക ക്വിസ് മത്സരം."}]}'::jsonb, 7)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2027-02', '{"index":8,"monthKey":"2027-02","monthEn":"FEBRUARY 2027","monthMl":"ഫെബ്രുവരി","accent":"#E8A878","actionTheme":"നോമ്പ് കാല മാസം","churchLine":"ദേവാലയം പണിയുന്നു · കാരുണ്യ കവാടം","churchPart":{"ml":"കാരുണ്യ കവാടം","en":"Mercy Gate","index":8,"total":11},"tagline":"ഹൃദയം നുറുക്കി മടങ്ങുവിൻ","description":"പ്രാർത്ഥനയും ഉപവാസവും കാരുണ്യവും ചേർന്ന നോമ്പുകാല ഒരുക്കത്തിന്റെ മാസം.","virtue":"കാരുണ്യം","stones":["ഒരു കാരുണ്യ പ്രവൃത്തി ചെയ്യുക","ദരിദ്രരോടൊപ്പം സമയം ചെലവഴിക്കുക","പ്രകൃതിയെ സംരക്ഷിക്കുക"],"feastDays":[{"date":"10 ഫെബ്രു","day":"ബുധൻ","name":"ഭസ്മ ബുധൻ · നോമ്പാരംഭം","type":"നോമ്പ്"}],"programs":[{"title":"100 കാരുണ്യ പ്രവർത്തനങ്ങൾ","desc":"നോമ്പുകാലത്ത് കാരുണ്യ പ്രവൃത്തികളുടെ ദൗത്യം."},{"title":"നോമ്പ് ധ്യാനം","desc":"നോമ്പുകാല ഒരുക്കത്തിനായി ധ്യാനം."},{"title":"കുരിശിന്റെ വഴി","desc":"എല്ലാ വെള്ളിയാഴ്ചയും കുരിശിന്റെ വഴി."},{"title":"ദരിദ്രരോടൊപ്പം ഒരു ദിവസം","desc":"ദരിദ്രരോടൊപ്പം ചെലവഴിക്കുന്ന ദിവസം."}]}'::jsonb, 8)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2027-03', '{"index":9,"monthKey":"2027-03","monthEn":"MARCH 2027","monthMl":"മാർച്ച്","accent":"#C68FBE","actionTheme":"വിശ്വാസ ജീവിത മാസം","churchLine":"ദേവാലയം പണിയുന്നു · വിശുദ്ധ കുർബാന മണ്ഡപം","churchPart":{"ml":"വിശുദ്ധ കുർബാന മണ്ഡപം","en":"Eucharistic Sanctuary","index":9,"total":11},"tagline":"വിശ്വാസം ജീവിതമാകുമ്പോൾ","description":"വിശുദ്ധ കുർബാനയുടെയും ആരാധനയുടെയും ആഴം അനുഭവിച്ചറിയുക.","virtue":"വിശുദ്ധി","stones":["വി. കുർബാന ആഴത്തിൽ അനുഭവിക്കുക","കുമ്പസാരത്തിന് പോകുക","വിശുദ്ധ വാര ധ്യാനത്തിൽ പങ്കെടുക്കുക"],"feastDays":[{"date":"21 മാർച്ച്","day":"ഞായർ","name":"ഓശാന ഞായർ","type":"ലിറ്റർജി"},{"date":"25 മാർച്ച്","day":"വ്യാഴം","name":"പെസഹ വ്യാഴം","type":"ലിറ്റർജി"},{"date":"26 മാർച്ച്","day":"വെള്ളി","name":"ദുഃഖവെള്ളി","type":"ലിറ്റർജി"},{"date":"28 മാർച്ച്","day":"ഞായർ","name":"ഉയിർപ്പ് തിരുനാൾ (ഈസ്റ്റർ)","type":"തിരുനാൾ"}],"programs":[{"title":"കുർബാന ട്രഷർ ഹണ്ട്","desc":"വിശുദ്ധ കുർബാനയെ അറിയുന്ന കളി."},{"title":"ആരാധന ശില്പശാല","desc":"ആരാധനയുടെ അർത്ഥം പകരുന്ന ശില്പശാല."},{"title":"വിശുദ്ധ വാര ധ്യാനം","desc":"വിശുദ്ധ വാരത്തിലെ ധ്യാന ഒരുക്കം."},{"title":"ഈസ്റ്റർ ആഘോഷം","desc":"ഉയിർപ്പ് തിരുനാൾ സമൂഹ ആഘോഷം."}]}'::jsonb, 9)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2027-04', '{"index":10,"monthKey":"2027-04","monthEn":"APRIL 2027","monthMl":"ഏപ്രിൽ","accent":"#C2B95F","actionTheme":"നേതൃത്വ മാസം","churchLine":"ദേവാലയം പണിയുന്നു · നേതൃത്വ മണിഗോപുരം","churchPart":{"ml":"നേതൃത്വ മണിഗോപുരം","en":"Leadership Bell Tower","index":10,"total":11},"tagline":"ചെറുപുഷ്പങ്ങളിൽ നിന്ന് നേതാക്കളിലേക്ക്","description":"നാളെയുടെ സഭാ-സാമൂഹിക നേതാക്കളെ രൂപപ്പെടുത്തുന്ന പരിശീലന പരമ്പര.","virtue":"ഉത്തരവാദിത്വം","stones":["ഒരു സംഘത്തെ നയിക്കുക","പരസ്യമായി സംസാരിക്കാൻ പഠിക്കുക","ഒരു നല്ല മാതൃകയാകുക"],"feastDays":[{"date":"4 ഏപ്രിൽ","day":"ഞായർ","name":"ദിവ്യകാരുണ്യ ഞായർ","type":"തിരുനാൾ"}],"programs":[{"title":"നേതൃത്വ ക്യാമ്പ്","desc":"നേതൃപാടവം വളർത്തുന്ന പരിശീലന ക്യാമ്പ്."},{"title":"പൊതുപ്രസംഗ പരിശീലനം","desc":"ആത്മവിശ്വാസത്തോടെ സംസാരിക്കാൻ പരിശീലനം."},{"title":"മീഡിയ പരിശീലനം","desc":"ഡിജിറ്റൽ-മാധ്യമ നൈപുണ്യ പരിശീലനം."},{"title":"യുവജന സഭ","desc":"യുവജനങ്ങൾ നയിക്കുന്ന മാതൃകാ സഭാ സമ്മേളനം."}]}'::jsonb, 10)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

INSERT INTO plan_content (key, value, sort_order) VALUES ('pravarthana-2026-27:2027-05', '{"index":11,"monthKey":"2027-05","monthEn":"MAY 2027","monthMl":"മേയ്","accent":"#E2876F","actionTheme":"നസ്രാണി ക്വസ്റ്റ് 2027","churchLine":"","churchPart":{"ml":"പൂർത്തിയായ ദേവാലയം","en":"Completed Church","index":11,"total":11},"tagline":"വേരുകളിൽ നിന്ന് ദൗത്യത്തിലേക്ക്","description":"ചരിത്രം, വിശ്വാസം, സേവനം, നേതൃത്വം എന്നിവ സംയോജിപ്പിച്ച വർഷാവസാന മഹാ സാഹസിക മത്സരം.","virtue":"സന്തോഷം","stones":["വർഷത്തെ കല്ലുകൾ സമർപ്പിക്കുക","ദേവാലയ മാതൃക പൂർത്തിയാക്കുക","സ്വന്തം സാക്ഷ്യം പങ്കിടുക"],"feastDays":[{"date":"1 മേയ്","day":"ശനി","name":"വി. യൗസേപ്പ് തൊഴിലാളി","type":"തിരുനാൾ"}],"programs":[{"title":"നസ്രാണി ഹെറിറ്റേജ് ഗ്രാമം","desc":"വർഷം മുഴുവൻ പണിത ദേവാലയ മാതൃകയുടെ പ്രദർശന ഗ്രാമം."},{"title":"ചരിത്ര ഗാലറി","desc":"ശേഖരിച്ച ചരിത്ര വസ്തുക്കളുടെ ഗാലറി."},{"title":"മിഷൻ സോൺ","desc":"മിഷൻ പ്രവർത്തനങ്ങളുടെ അനുഭവ മേഖല."},{"title":"സമൂഹ സേവന പ്രദർശനം","desc":"വർഷത്തെ സേവന പ്രവർത്തനങ്ങളുടെ പ്രദർശനം."},{"title":"അവാർഡ് ദാനം","desc":"മികച്ച പ്രവർത്തനങ്ങൾക്ക് പുരസ്കാര വിതരണം."}]}'::jsonb, 11)
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, sort_order=EXCLUDED.sort_order, updated_at=now();

